        return false;
    }

    void resizeAndPut(long long x, long long v) {
        int nscale = scale << 1;
        int nrscale = rscale << 1;
        int nmask = nscale - 1;
        vector<long long> nkeys(nscale, 0);
        vector<long long> nvals(nscale, NG);
        for (int i = next(0); i < scale; i = next(i+1)) {
            long long y = keys[i];
            int pos = h(y) & nmask;
            while (nvals[pos] != NG) pos = (pos + 1) & nmask;
            nkeys[pos] = y;
            nvals[pos] = vals[i];
        }
        {
            int pos = h(x) & nmask;
            while (nvals[pos] != NG) pos = (pos + 1) & nmask;
            nkeys[pos] = x;
            nvals[pos] = v;
        }
        keys.swap(nkeys);
        vals.swap(nvals);
        scale = nscale;
        rscale = nrscale;
        mask = nmask;
    }

    int next(int itr) {
        while (itr < scale && vals[itr] == NG) itr++;
        return itr;
    }

    int h(long long x) {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdLL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53LL;
        x ^= x >> 33;
        return (int)x;
    }
};

// Meissel-Lehmer prime counting algorithm
struct MeisselLehmer2 {
    vector<int> primes;
    vector<int> xcums;
    vector<long long> isp;
    int cachelimit;
    LongHashCounterL picache;
    LongHashCounterL phicache;
    bool cachePhi;
    vector<vector<int>> cumps;
    vector<int> FP;
    int M;
    int B;

    MeisselLehmer2(long long n) {
        assert(n >= 4);
        cachePhi = true;
        B = 100;
        int s = (int)sqrt(n) * B;
        cachelimit = s;
        primes = sieveEratosthenes(s);
        xcums.assign((s>>6)+1, 0);
        isp.assign((s>>6)+1, 0);
        for (int p : primes) isp[p>>6] |= 1LL << p;
        for (int i = 0; i < (int)xcums.size()-1; i++) xcums[i+1] = xcums[i] + __builtin_popcountll(isp[i]);
        FP = {2,3,5,7,11,13,17,19};
        M = FP.size();
        cumps.resize(M);
        vector<bool> b = {true};
        int len = 1;
        for (int i = 0; i < M; i++) {
            len *= FP[i];
            vector<bool> c(len, false);
            for (int j = 0; j < FP[i]; j++) {
                copy(b.begin(), b.end(), c.begin() + j*b.size());
            }
            for (int k = 0; k < len; k += FP[i]) c[k] = false;
            cumps[i].resize(len+1);
            for (int j = 0; j < len; j++) cumps[i][j+1] = cumps[i][j] + (c[j] ? 1 : 0);
            FP[i] = len;
            b = c;
        }
    }

    long long sqrt(long long n) {
        long long i = max(0LL, (long long)::sqrt(n)-2);
        while (i*i <= n) i++;
        return i-1;
    }

    long long cbrt(long long n) {
        long long i = max(0LL, (long long)::cbrt(n)-2);
        while (i*i*i <= n) i++;
        return i-1;
    }

    long long pi(long long x) {
        if (x <= cachelimit) {
            int ix = (int)x;
            int shift = 63 - (ix & 63);
            long long mask = isp[ix>>6] << shift;
            return xcums[ix>>6] + __builtin_popcountll(mask);
        }
        if (picache.containsKey(x)) return picache.get(x);
        int A = (int)pi(sqrt(sqrt(x)));
        long long ret = A + phi(x, A) - P2(x, A) - P3(x, A) - 1;
        picache.put(x, ret);
        return ret;
    }

    long long phi(long long x, int A) {
        if (A > 0 && A-1 < M) {
            return cumps[A-1][FP[A-1]] * (x / FP[A-1]) + cumps[A-1][(int)(x % FP[A-1] + 1)];
        }
        if (A > 0 && x <= (long long)primes[A-1] * primes[A-1]) {
            return pi(x) - A + 1;
        }
        long long code = (x << 13) | A;
        if (phicache.containsKey(code)) return phicache.get(code);
        long long ret = x;
        for (int i = A-1; i >= 0; i--) ret -= phi(x / primes[i], i);
        if (cachePhi) phicache.put(code, ret);
        return ret;
    }

    long long P2(long long x, int A) {
        int B = (int)pi(sqrt(x));
        long long ret = 0;
        for (int i = A; i < B; i++) {
            ret += pi(x / primes[i]);
        }
        ret -= (long long)(B - A) * (B + A - 1) / 2;
        return ret;
    }

    long long P3(long long x, int A) {
        int C = (int)pi(cbrt(x));
        long long ret = 0;
        for (int i = A; i < C; i++) {
            long long xi = x / primes[i];
            int B = (int)pi(sqrt(xi));
            for (int j = i; j < B; j++) {
                ret += pi(xi / primes[j]) - j;
            }
        }
        return ret;
    }
};

// Global primes up to 400000
vector<int> primes = sieveEratosthenes(400000);

void solve() {
    long long n = readLong();
    long long ans = 0;
    MeisselLehmer2 ml(n/2);
    for (int i = 0; i < (int)primes.size(); i++) {
        long long plus = ml.pi(n / primes[i]) - (i+1);
        if (plus <= 0) break;
        ans += plus;
    }
    for (int p : primes) {
        if ((long long)p * p * p <= n) {
            ans++;
        } else {
            break;
        }
    }
    printf("%lld\n", ans);
}

